	getFaqsData() {
		const obj = {
			type: 'Ecommerce'
		}
		this.faqService.getFaqs(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.ecommerceFaqs = res?.result;
				this.addFaqSchema();
				this.cdr.markForCheck();

			}
		})
	}
	getTestimonialsData() {
		const obj = {
			type: 'ecommerce'
		}
		this.testimonialService.getAlltestimonial(obj).subscribe((res: any) => {
			if (res.code == 200) {
				this.ecommerceTestimonials = res?.result?.filter((item: any) =>
					item.categorydata?.some(
						(cat: any) => cat.name?.toLowerCase() === 'ecommerce'
					)
				);
				this.cdr.markForCheck();
			}
		})
	}
